package com.immersio.scenarios.api;
import com.immersio.scenarios.api.dto.*; import com.immersio.scenarios.service.ScenarioService; import com.immersio.shared.dto.ApiResponse; import com.immersio.shared.security.JwtTokenProvider; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/scenarios") public class ScenariosController { private final ScenarioService service; private final JwtTokenProvider jwt; public ScenariosController(ScenarioService s,JwtTokenProvider j){service=s;jwt=j;} private UUID user(String h){return jwt.extractUserId(h.replace("Bearer ",""));}
 @GetMapping public ApiResponse<List<ScenarioDto>> all(){return ApiResponse.successResult(service.getScenarios());} @GetMapping("/{id}") public ApiResponse<ScenarioDto> one(@PathVariable UUID id){return ApiResponse.successResult(service.getScenarioById(id));}
 @PostMapping("/sessions/start") public ApiResponse<StartSessionResponse> start(@RequestHeader("Authorization") String h,@RequestBody StartSessionRequest r){return ApiResponse.successResult(service.startSession(user(h),r));} @PostMapping("/sessions/{id}/chat") public ApiResponse<ChatOutputResponse> chat(@RequestHeader("Authorization") String h,@PathVariable UUID id,@RequestBody ChatInputRequest r){return ApiResponse.successResult(service.sendMessage(user(h),id,r));} @PostMapping("/sessions/{id}/finish") public ApiResponse<FinishSessionResponse> finish(@RequestHeader("Authorization") String h,@PathVariable UUID id){return ApiResponse.successResult(service.completeSession(user(h),id));} @PostMapping("/sessions/{id}/flashcards") public ApiResponse<Map<String,Object>> flash(@RequestHeader("Authorization") String h,@PathVariable UUID id,@RequestBody GenerateFlashcardsRequest r){return ApiResponse.successResult(service.generateCustomFlashcards(user(h),id,r));}
 @PostMapping @PreAuthorize("hasRole('Admin')") public ApiResponse<ScenarioDto> create(@RequestBody CreateScenarioDto r){return ApiResponse.successResult(service.createScenario(r));} @PutMapping("/{id}") @PreAuthorize("hasRole('Admin')") public ApiResponse<ScenarioDto> update(@PathVariable UUID id,@RequestBody CreateScenarioDto r){return ApiResponse.successResult(service.updateScenario(id,r));} @DeleteMapping("/{id}") @PreAuthorize("hasRole('Admin')") public ApiResponse<Void> delete(@PathVariable UUID id){service.deleteScenario(id);return ApiResponse.successResult(null);} @PostMapping("/{id}/items") @PreAuthorize("hasRole('Admin')") public ApiResponse<ScenarioItemDto> add(@PathVariable UUID id,@RequestBody CreateScenarioItemDto r){return ApiResponse.successResult(service.addScenarioItem(id,r));} }
